b, updated_at=now() WHERE slug='falcon-packaging-iowa' AND approved AND profile IS NULL;
UPDATE companies SET description='Falcon Sheet Metal was founded in 1979 by Willard Peck and his wife Ramona in Salt Lake City, Utah. The company, named after the falcon for its speed and precision, began in a small rented space and has since moved three times, now operating from its own 22,000-square-foot facility in North Salt Lake. Current owners are Riley Landsaw and Charlene Barton.

The shop provides sheet metal fabrication services including laser cutting, welding, machining, forming, punching, shearing, countersinking, tapping, brushing, and deburring. It also coordinates subcontracted finishing such as plating, powder coating, and painting. The 22,000-square-foot plant houses equipment for these processes, though specific machine models are not disclosed.

Falcon serves industrial customers such as Automated Technology, as noted in a testimonial from Janet Curl. The company works with businesses requiring precision sheet metal parts, though specific industry sectors are not detailed in public materials.

The founders chose the falcon as a symbol of speed and precision, and the company emphasizes an honest approach, stating they will tell a customer if they are not the right fit for a job. ISO certification underscores a commitment to quality management.', certifications=ARRAY['ISO Certified']::text[], profile='{"capabilities": ["Laser Cutting", "Welding", "Hardware installation", "Machining", "Countersinking", "Shearing", "Tapping", "Brushing", "Punching", "Forming", "Deburring", "Plating (subcontract)", "Powdercoat (subcontract)", "Painting (subcontract)"], "industries": [], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Honest assessment: tells customers if they are not the right fit", "ISO certified quality management", "22,000-square-foot owned facility in North Salt Lake", "Family-founded in 1979, named for falcon speed and precision", "In-house laser cutting, welding, machining, and forming with subcontracted finishing"], "facts_used": ["Founded in 1979 by Willard Peck and Ramona Peck -> /about", "Named after falcon bird for speed and precision -> /about", "Started in small rented space in Salt Lake City, moved three times, now in 22,000-square-foot building in North Salt Lake -> /about", "Current owners: Riley Landsaw and Charlene Barton -> /about", "Services: Laser Cutting, Welding, Hardware, Machining, Countersinking, Shearing, Tapping, Brushing, Punching, Forming, Deburring -> /services", "Subcontracted services: plating, powdercoat, painting -> /services", "ISO Certified -> /", "Customer testimonial from Janet Curl of Automated Technology -> /", "Company states: ''As an honest company, we will let you know if we are the right fit for the job.'' -> /", "Location: 850 Northpointe, North Salt Lake, Utah, 84054 -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "HIGH QUALITY SHEET METAL FABRICATION", "founded_year": "1979", "employee_count": "", "cage_code": "